      if ((pad.buttons[15]?.pressed && !previousButtons[15]) || (x === 1 && previousAxisX !== 1)) move('right');
      if ((pad.buttons[12]?.pressed && !previousButtons[12]) || (y === -1 && previousAxisY !== -1)) move('up');
